'use strict';
let starterModule=null,starterCache=null,starterSource=null,starterGain=null,starterEpoch=0,starterBusy=false;
const starterCatalog=[['house','House','Kick rond · basse · accord mineur'],['boombap','Boom bap','Batterie mate · basses chaleureuses'],['electro','Electro','Percussions synthétiques · basse mordante'],['ambient','Ambient','Percussions douces · nappes aériennes']];
function stopStarterPreview(){starterEpoch++;try{starterSource?.stop();starterSource?.disconnect();starterGain?.disconnect()}catch{}starterSource=null;starterGain=null}
async function ensureStarterEngine(){if(typeof PocketStarter!=='undefined')return PocketStarter;if(!starterModule)starterModule=import('./starter-engine.js?v=18').then(()=>PocketStarter).catch(e=>{starterModule=null;throw e});return starterModule}
async function starterSounds(id){if(starterCache?.id===id)return starterCache.sounds;const engine=await ensureStarterEngine(),sounds=await engine.build(id,sr);starterCache={id,sounds};return sounds}
function refreshStarterBank(){const b=+$('#starterDestination').value,occupied=pads.slice(b*16,b*16+16).some(p=>p.data.length>1);$('#starterLoadKit').textContent=(occupied?'REMPLACER':'CHARGER')+' LES 16 PADS DE '+String.fromCharCode(65+b);$('#starterDestinationNote').textContent=occupied?'Cette banque contient des sons : ils seront remplacés. ↶ ANNULER les récupère. Les séquences sont conservées.':'Banque vide : vos sons existants sont conservés.';$('#starterLoadSound').textContent='CHARGER CE SON SUR '+padName(selected);$('#starterReplacement').textContent=padName(b*16)+' / '+pads[b*16].name+' → '+starterCatalog.find(k=>k[0]===$('#starterKit').value)[1].toUpperCase()+' KICK · premier des 16 sons remplacés'}
function openStarterBank(){stopStarterPreview();$('#starterDestination').value=bank;refreshStarterBank();$('#starterDialog').showModal()}
async function playStarterPreview(whole=false){stopStarterPreview();const request=starterEpoch,id=$('#starterKit').value,index=+$('#starterSound').value,owner=pads;$('#starterState').textContent='Préparation de l’aperçu…';try{await audio();const engine=await ensureStarterEngine();if(request!==starterEpoch||pads!==owner||!$('#starterDialog').open)return;const data=whole?engine.preview(await starterSounds(id),engine.kits.find(k=>k.id===id).bpm,sr):engine.sound(id,index,sr).data;if(request!==starterEpoch||pads!==owner||!$('#starterDialog').open)return;const buffer=ctx.createBuffer(1,data.length,sr);buffer.copyToChannel(data,0);const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;gain.gain.value=+$('#master').value/100*.65;source.connect(gain).connect(ctx.destination);starterSource=source;starterGain=gain;source.onended=()=>{source.disconnect();gain.disconnect();if(starterSource===source){starterSource=null;starterGain=null;$('#starterState').textContent='Aperçu terminé.'}};source.start();$('#starterState').textContent=whole?'Aperçu sec du kit · tempo indicatif uniquement, votre projet ne change pas.':'Écoute du son sans les effets du projet.'}catch(e){if(request===starterEpoch)$('#starterState').textContent=e.message}}
async function loadStarterSounds(whole=false){if(starterBusy)return;starterBusy=true;const owner=pads,id=$('#starterKit').value,index=+$('#starterSound').value,first=whole?+$('#starterDestination').value*16:selected;stopStarterPreview();$('#starterLoadKit').disabled=$('#starterLoadSound').disabled=true;$('#starterState').textContent='Préparation des sons…';try{const engine=await ensureStarterEngine(),sounds=whole?await starterSounds(id):[engine.sound(id,index,sr)];if(owner!==pads||!$('#starterDialog').open)throw Error('Chargement annulé : le projet ou la fenêtre a changé.');const targets=new Set(sounds.map((_,i)=>first+i));const total=pads.reduce((n,p,i)=>n+(targets.has(i)?0:p.data.length*(p.right?2:1)),0)+sounds.reduce((n,s)=>n+s.data.length,0);if(total>sr*240)throw Error('Mémoire audio pleine : libérez des sons avant de charger ce kit.');remember();for(let n=0;n<sounds.length;n++){const i=first+n,old=pads[i],sound=sounds[n];stopPad(i);clearIndividual(i);const fresh={...createPad(16),...cleanPadSettings({}),name:sound.name.slice(0,24),data:sound.data.slice(),patterns:old.patterns,events:old.events,automation:old.automation||{},chokeGroup:sound.kind==='hat'?Math.floor(i/16)+1:0,polyphony:sound.kind==='bass'?'mono':'poly'};pads[i]=fresh;if(typeof warpCache!=='undefined')for(const key of [...warpCache.keys()])if(+key.split(':')[0]===i)warpCache.delete(key)}sequenceSurface=false;chopSurface=false;selectOnly=false;$('#selectOnly').classList.remove('active');$('#selectOnly').setAttribute('aria-pressed',false);updateSelected(first);routePadBuses(false);changed();clearTimeout(saveTimer);$('#starterState').textContent='Sons remplacés · enregistrement sur cet appareil…';const persisted=await saveLocal();$('#starterDialog').close();status((whole?'Kit '+starterCatalog.find(k=>k[0]===id)[1]+' chargé en banque '+String.fromCharCode(65+first/16):'Son chargé sur '+padName(first))+(persisted?' · enregistré sur cet appareil.':' · chargé en mémoire ; sauvegarde locale indisponible, exportez ↓ PROJET.')+' ↶ ANNULER restaure les sons précédents.')}catch(e){$('#starterState').textContent=e.message}finally{starterBusy=false;$('#starterLoadKit').disabled=$('#starterLoadSound').disabled=false}}
if(!window.POCKET_PARITY_TEST){$('#starterOpen').onclick=openStarterBank;$('#starterClose').onclick=()=>$('#starterDialog').close();$('#starterDialog').addEventListener('close',stopStarterPreview);$('#starterDialog').addEventListener('cancel',stopStarterPreview);$('#starterKit').onchange=()=>{stopStarterPreview();$('#starterState').textContent=starterCatalog.find(k=>k[0]===$('#starterKit').value)[2];refreshStarterBank()};$('#starterSound').onchange=stopStarterPreview;$('#starterDestination').onchange=refreshStarterBank;$('#starterPreviewSound').onclick=()=>playStarterPreview(false);$('#starterPreviewKit').onclick=()=>playStarterPreview(true);$('#starterStop').onclick=stopStarterPreview;$('#starterLoadSound').onclick=()=>loadStarterSounds(false);$('#starterLoadKit').onclick=()=>loadStarterSounds(true);const oldRestore=restore;restore=o=>{stopStarterPreview();$('#starterDialog').close();oldRestore(o)};const oldPanic=$('#panic').onclick;$('#panic').onclick=()=>{stopStarterPreview();oldPanic()};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopStarterPreview()});window.addEventListener('pagehide',stopStarterPreview)}
